    wkv=mmap(sh24,'layers.24.attn.wkv.weight',np.uint8,(D,DIM)); wkvs=mmap(sh24,'layers.24.attn.wkv.scale',np.uint8,(D//32,DIM//32)); kvnw=mmap(sh24,'layers.24.attn.kv_norm.weight',np.uint16,(D,)); window_norm=rms(fp8_linear(x2,np.ascontiguousarray(wkv),np.ascontiguousarray(wkvs)),np.ascontiguousarray(kvnw)); wrot=rotary_any(window_norm.reshape(1,S,D),c,s); _,_,window_flat=act_quant(wrot.reshape(S,D)); window_kv=window_flat.reshape(1,S,D); wtopk=window_topk(S)
